static int amd64_fetch_size ( void ) { struct pci_dev * dev ; int i ; u32 temp ; struct aper_size_info_32 * values ; dev = node_to_amd_nb ( 0 ) -> misc ; pci_read_config_dword ( dev , AMD64_GARTAPERTURECTL , & temp ) ; temp = ( temp & 0xe ) ; values = A_SIZE_32 ( amd64_aperture_sizes ) ; for ( i = 0 ; i < agp_bridge -> driver -> num_aperture_sizes ; i ++ ) { if ( temp == values [ i ] . size_value ) { agp_bridge -> previous_size = agp_bridge -> current_size = ( void * ) ( values + i ) ; agp_bridge -> aperture_size_idx = i ; return values [ i ] . size ; } } return 0 ; } 